"use client"

import React, { useState } from 'react'
import Link from 'next/link'
import { useRouter } from 'next/navigation'
import { ArrowLeft, Loader2 } from 'lucide-react'

export default function LoginPage() {
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [isLoading, setIsLoading] = useState(false)
  const [error, setError] = useState('')
  const router = useRouter()

  const handleLogin = async (e: React.FormEvent) => {
    e.preventDefault()
    setIsLoading(true)
    setError('')

    try {
      // Mock API Call
      await new Promise(resolve => setTimeout(resolve, 1500))
      localStorage.setItem('TOKEN', 'mock_token_123')
      router.push('/dashboard')
    } catch (err: any) {
      setError('Login gagal. Silakan periksa kembali email dan password Anda.')
    } finally {
      setIsLoading(false)
    }
  }

  return (
    <div className="min-h-screen bg-[#f8faf8] flex flex-col items-center justify-center p-6 relative overflow-hidden">
      {/* Decorative Blobs */}
      <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-green-100 rounded-full blur-[120px] animate-blob -z-0" />
      <div className="absolute bottom-0 left-0 w-[500px] h-[500px] bg-emerald-50 rounded-full blur-[120px] animate-blob animation-delay-2000 -z-0" />

      <div className="w-full max-w-md bg-white/80 backdrop-blur-xl p-10 rounded-[2.5rem] shadow-2xl border border-white/60 relative z-10">
        <div className="flex flex-col items-center mb-10">
          <div className="w-12 h-12 bg-[#0a0f0a] rounded-xl flex items-center justify-center font-display font-bold text-tsGreen text-2xl mb-4">
            T
          </div>
          <h2 className="font-display font-black text-3xl text-stone-900 mb-2">Selamat Datang</h2>
          <p className="text-stone-500 text-sm font-body">Masuk untuk mengelola nutrisi tanaman Anda.</p>
        </div>

        {error && (
          <div className="bg-red-50 border border-red-200 text-red-600 px-4 py-3 rounded-2xl text-sm mb-6 flex items-center gap-3">
            <span className="text-xl">⚠️</span>
            {error}
          </div>
        )}

        <form onSubmit={handleLogin} className="space-y-4">
          <div>
            <label className="block text-xs font-mono font-bold text-stone-400 uppercase tracking-widest mb-2 ml-1">Email</label>
            <input 
              type="email" 
              required
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className="w-full bg-stone-100 border-none rounded-2xl px-5 py-4 text-stone-900 focus:ring-2 focus:ring-green-500 outline-none transition-all placeholder:text-stone-400"
              placeholder="nama@email.com"
            />
          </div>

          <div>
            <div className="flex items-center justify-between mb-2 px-1">
              <label className="text-xs font-mono font-bold text-stone-400 uppercase tracking-widest">Password</label>
              <Link href="#" className="text-xs font-bold text-green-600 hover:underline">Lupa Password?</Link>
            </div>
            <input 
              type="password" 
              required
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="w-full bg-stone-100 border-none rounded-2xl px-5 py-4 text-stone-900 focus:ring-2 focus:ring-green-500 outline-none transition-all placeholder:text-stone-400"
              placeholder="••••••••"
            />
          </div>

          <button 
            type="submit"
            disabled={isLoading}
            className="w-full bg-green-600 hover:bg-green-700 text-white font-black py-4 rounded-2xl transition-all shadow-lg shadow-green-600/20 flex items-center justify-center gap-2 mt-4"
          >
            {isLoading ? (
              <>
                <Loader2 className="w-5 h-5 animate-spin" />
                Sedang masuk...
              </>
            ) : (
              'Masuk Sekarang'
            )}
          </button>
        </form>

        <div className="mt-10 text-center">
          <p className="text-sm text-stone-500 mb-6">
            Belum punya akun? <Link href="/register" className="text-green-600 font-bold hover:underline">Daftar Sekarang</Link>
          </p>
        </div>
      </div>

      <button 
        onClick={() => router.push('/')}
        className="mt-8 flex items-center gap-2 text-stone-500 hover:text-stone-900 font-bold text-sm transition-all"
      >
        <ArrowLeft className="w-4 h-4" />
        Kembali ke Beranda
      </button>
    </div>
  )
}